import type { Metadata } from "next"

export const SITE_URL = "https://www.jorenbagadiong.dev"
export const SITE_NAME = "Joren Bagadiong – Frontend Developer"

/** "[Page] | Joren Bagadiong – Frontend Developer" */
export const fullTitle = (page: string) => `${page} | ${SITE_NAME}`

/**
 * Per-page metadata. The title is absolute because the root layout's
 * template skips app/page.tsx. A page's `openGraph`/`twitter` replace the
 * inherited ones whole, so the images (generated by app/opengraph-image.tsx
 * and app/twitter-image.tsx) are listed again here.
 */
export function pageMetadata({
  title,
  description,
  path,
}: {
  title: string
  description: string
  path: string
}): Metadata {
  const full = fullTitle(title)
  return {
    title: { absolute: full },
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      siteName: SITE_NAME,
      locale: "en_US",
      url: path,
      title: full,
      description,
      images: [
        { url: "/opengraph-image", width: 1200, height: 630, alt: SITE_NAME },
      ],
    },
    twitter: {
      card: "summary_large_image",
      title: full,
      description,
      images: [{ url: "/twitter-image", alt: SITE_NAME }],
    },
  }
}
